INSERT INTO quizzes (module_id, title, pass_pct, points, active, updated_at) SELECT module_id, 'Prova do módulo CRM', 60, 30, 1, NOW() FROM modules WHERE system_id = 'e-trade' AND name = 'CRM' AND NOT EXISTS (SELECT 1 FROM quizzes q JOIN modules m2 ON m2.module_id = q.module_id WHERE m2.system_id = 'e-trade' AND m2.name = 'CRM') LIMIT 1;
INSERT INTO quiz_questions (quiz_id, position, question, options, correct, explanation) SELECT q.quiz_id, 1, 'No cadastro de cliente, qual tecla de atalho busca os dados da empresa direto na Receita/SEFAZ a partir do CNPJ?', '["F2", "F6", "F9", "F12"]', 1, 'O F6 (ou o botão ao lado do campo) consulta os dados na Receita. Já o F7 consulta a inscrição estadual, e só funciona com o CNPJ e a UF preenchidos.' FROM quizzes q JOIN modules m ON m.module_id = q.module_id WHERE m.system_id = 'e-trade' AND m.name = 'CRM' AND NOT EXISTS (SELECT 1 FROM quiz_questions qq WHERE qq.quiz_id = q.quiz_id AND qq.position = 1);
INSERT INTO quiz_questions (quiz_id, position, question, options, correct, explanation) SELECT q.quiz_id, 2, 'Na captura de dados do cliente, o que a versão paga (com token da SEFAZ) traz a mais que a versão gratuita?', '["O telefone e o e-mail do contador", "A foto da fachada da empresa", "A inscrição estadual", "O limite de crédito do cliente"]', 2, 'Na versão paga, além de nome, endereço e CNPJ, o sistema já traz a inscrição estadual. Na gratuita ela não vem, e há um atalho que abre o site da SEFAZ do estado para consultar.' FROM quizzes q JOIN modules m ON m.module_id = q.module_id WHERE m.system_id = 'e-trade' AND m.name = 'CRM' AND NOT EXISTS (SELECT 1 FROM quiz_questions qq WHERE qq.quiz_id = q.quiz_id AND qq.position = 2);
INSERT INTO quiz_questions (quiz_id, position, question, options, correct, explanation) SELECT q.quiz_id, 3, 'Você configurou um “Limite de crédito padrão” de R$ 400 no cadastro de clientes. Para quais clientes esse valor vale?', '["Para todos os clientes, inclusive os já cadastrados", "Só para os clientes novos, cadastrados depois da configuração", "Só para clientes cadastrados no PDV", "Só para clientes com SPC “nada consta”"]', 1, 'O limite padrão é preenchido automaticamente apenas nos clientes novos (no retaguarda, PDV ou Gourmet). Os clientes que já existem não mudam, e o valor sempre pode ser alterado à mão.' FROM quizzes q JOIN modules m ON m.module_id = q.module_id WHERE m.system_id = 'e-trade' AND m.name = 'CRM' AND NOT EXISTS (SELECT 1 FROM quiz_questions qq WHERE qq.quiz_id = q.quiz_id AND qq.position = 3);
INSERT INTO quiz_questions (quiz_id, position, question, options, correct, explanation) SELECT q.quiz_id, 4, 'Um cliente com senha de venda esqueceu a senha no caixa. Como o operador libera a venda sem a senha, se tiver permissão?', '["Apertando F12 para liberar a venda sem senha", "Excluindo o cadastro do cliente", "Trocando a venda para “à vista”", "Não é possível vender sem a senha"]', 0, 'O F12 libera a venda sem a senha (permissão 500). A permissão 501 permite ver a senha no cadastro, pelo botão do olho. Lembre: a senha diferencia maiúsculas de minúsculas.' FROM quizzes q JOIN modules m ON m.module_id = q.module_id WHERE m.system_id = 'e-trade' AND m.name = 'CRM' AND NOT EXISTS (SELECT 1 FROM quiz_questions qq WHERE qq.quiz_id = q.quiz_id AND qq.position = 4);
INSERT INTO quiz_questions (quiz_id, position, question, options, correct, explanation) SELECT q.quiz_id, 5, 'Como obrigar o preenchimento de campos como bairro e CNPJ no cadastro de cliente?', '["Não tem como, todos os campos são opcionais", "Em “Configurar”, na tela de cadastro do cliente, marcando os campos obrigatórios", "Bloqueando o cliente no SPC", "Cadastrando o cliente só pelo PDV"]', 1, 'Na tela de cadastro de cliente, em “Configurar”, você marca os campos obrigatórios. Também existe uma permissão no grupo de funcionários que obriga certos usuários a preencher todos os dados.' FROM quizzes q JOIN modules m ON m.module_id = q.module_id WHERE m.system_id = 'e-trade' AND m.name = 'CRM' AND NOT EXISTS (SELECT 1 FROM quiz_questions qq WHERE qq.quiz_id = q.quiz_id AND qq.position = 5);
